#include <bits/stdc++.h>
using namespace std;

long long p, k, visited[1000006], answer;

long long power_mod(long long base, long long exp) {
    long long result = 1;
    for (int i = 30; i >= 0; i--) {
        result = (result * result) % 1000000007;
        if ((1LL << i) & exp) {
            result = (result * base) % 1000000007;
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    answer = 0;
    cin >> p >> k;
    if (k == 1) {
        cout << power_mod(p, p);
        return 0;
    }
    for (int i = 1; i < p; i++) {
        if (!visited[i]) {
            visited[i] = 1;
            answer++;
            long long current = (i * k) % p;
            while (!visited[current]) {
                visited[current] = 1;
                current = (current * k) % p;
            }
        }
    }
    cout << power_mod(p, answer);
}
